const scratch = process.env.HIMAWARI_PROBE_SCRATCH ?? os.tmpdir();
if (process.platform === "linux" && !scratch.startsWith("/data/"))
  throw new Error("LINUX_PROBE_REQUIRES_DATA_DISK");

const parent = await realpath(process.env.HIMAWARI_PROBE_SCRATCH);
assert.ok(parent.startsWith("/data/himawari-r8-"));
assert.equal((await lstat(parent)).uid, process.getuid());

const scratchParent =
  process.platform === "linux" ? await realpath(process.env.HIMAWARI_PROBE_SCRATCH) : "/tmp";
if (process.platform === "linux" && !scratchParent.startsWith("/data/himawari-r8-"))
  throw new Error("LINUX_PROBE_REQUIRES_OWNED_DATA_DIRECTORY");
if (process.platform === "linux" && (await lstat(scratchParent)).uid !== process.getuid())
  throw new Error("LINUX_PROBE_DIRECTORY_OWNER_MISMATCH");

